
CREATE TABLE `dem_orders` (
                              `idorders` int NOT NULL AUTO_INCREMENT COMMENT 'Внутренний идентификатор',
                              `num_fer` varchar(32) CHARACTER SET cp1251 COLLATE cp1251_general_ci NOT NULL COMMENT 'Партия',
                              `numorders` varchar(32) CHARACTER SET cp1251 COLLATE cp1251_general_ci NOT NULL COMMENT 'Номер заказа',
                              `class_id` int NOT NULL DEFAULT '0' COMMENT 'id из таблицы dem_mat_class',
                              `ordername` varchar(255) CHARACTER SET cp1251 COLLATE cp1251_general_ci NOT NULL COMMENT 'Заказчик или объект',
                              `h_ord` int DEFAULT NULL,
                              `b_ord` int DEFAULT NULL,
                              `enginerid` int NOT NULL COMMENT 'id из таблицы dem_enginers',
                              `date` varchar(24) CHARACTER SET cp1251 COLLATE cp1251_general_ci DEFAULT NULL COMMENT 'Дата создания',
                              `start_date` int NOT NULL DEFAULT '0' COMMENT 'дата производства',
                              `ready_date` int NOT NULL DEFAULT '0' COMMENT 'дата готовности',
                              `ship_date` int NOT NULL DEFAULT '0' COMMENT 'дата отгрузки',
                              `date_postavka` int NOT NULL DEFAULT '0' COMMENT 'дата поставки',
                              `price_all` double NOT NULL DEFAULT '0',
                              `flag_exp` int DEFAULT '0' COMMENT 'Количество экспортировок',
                              `mon` int NOT NULL DEFAULT '0' COMMENT 'флаг монтажа',
                              `otk` int NOT NULL DEFAULT '0' COMMENT 'флаг откосов',
                              `ms` int NOT NULL DEFAULT '0' COMMENT 'флаг мс',
                              `vo` int NOT NULL DEFAULT '0' COMMENT 'флаг водоотливов',
                              `sp` int NOT NULL DEFAULT '0' COMMENT 'флаг сп',
                              `pod` int NOT NULL DEFAULT '0' COMMENT 'флаг подоконников',
                              `box` int NOT NULL DEFAULT '0' COMMENT 'флаг ящиков',
                              `mat` int NOT NULL DEFAULT '0' COMMENT 'флаг материалов',
                              `send` int NOT NULL DEFAULT '0' COMMENT 'флаг сэндвичей',
                              `klaes` int NOT NULL DEFAULT '0',
                              `gps` int NOT NULL DEFAULT '0',
                              `num_fer_dop` varchar(32) CHARACTER SET cp1251 COLLATE cp1251_general_ci DEFAULT NULL,
                              `link_order_box` int NOT NULL DEFAULT '0',
                              `made` int DEFAULT '0',
                              PRIMARY KEY (`numorders`,`class_id`,`ordername`,`price_all`,`num_fer`,`mon`,`otk`,`ms`,`vo`,`sp`,`pod`,`box`,`enginerid`) USING BTREE,
                              UNIQUE KEY `idorders` (`idorders`),
                              KEY `num_fer` (`num_fer`),
                              KEY `date` (`date`),
                              KEY `class_id` (`class_id`),
                              KEY `link_order_box` (`link_order_box`),
                              KEY `num_fer_dop` (`num_fer_dop`),
                              KEY `made` (`made`),
                              KEY `start_date` (`start_date`),
                              KEY `ready_date` (`ready_date`),
                              KEY `ship_date` (`ship_date`),
                              KEY `numorders` (`numorders`),
                              KEY `enginerid` (`enginerid`)
) ENGINE=MyISAM AUTO_INCREMENT=88 DEFAULT CHARSET=cp1251;

